import{_ as t,o as e,c as a,Q as d}from"./chunks/framework.742c4849.js";const u=JSON.parse('{"title":"AI 聊天机器人学习教程","description":"","frontmatter":{"title":"AI 聊天机器人学习教程"},"headers":[],"relativePath":"guide/ai/chatbot-course/index.md","filePath":"guide/ai/chatbot-course/index.md","lastUpdated":1792486784000}'),r={name:"guide/ai/chatbot-course/index.md"},i=d('<h1 id="ai-聊天机器人学习教程" tabindex="-1">AI 聊天机器人学习教程 <a class="header-anchor" href="#ai-聊天机器人学习教程" aria-label="Permalink to &quot;AI 聊天机器人学习教程&quot;">​</a></h1><p>从底层原理到工程实践的 40 篇中文文字教程，以 React、TypeScript、Node.js 为工程技术栈。</p><h2 id="已编写-01–09-篇" tabindex="-1">已编写：01–09 篇 <a class="header-anchor" href="#已编写-01–09-篇" aria-label="Permalink to &quot;已编写：01–09 篇&quot;">​</a></h2><p>当前已编写 <strong>9 / 40 篇（22.5%）</strong>。下列目录反映已有文章；内容编写、原稿校对和线上发布分别验收。</p><ol><li><a href="./01-how-chatgpt-works">第 01 篇：ChatGPT 如何回答问题</a></li><li><a href="./02-token-and-embedding">第 02 篇：Token 与 Embedding</a></li><li><a href="./03-transformer-attention">第 03 篇：Transformer 与 Attention</a></li><li><a href="./04-position-encoding">第 04 篇：位置编码与 RoPE</a></li><li><a href="./05-llm-training">第 05 篇：大语言模型是如何训练出来的？</a></li><li><a href="./06-inference">第 06 篇：模型推理与 KV Cache</a></li><li><a href="./07-model-limitations">第 07 篇：大模型的能力边界</a></li><li><a href="./08-prompt-messages">第 08 篇：Prompt 与 Messages</a></li><li><a href="./09-conversation-memory">第 09 篇：多轮对话与上下文管理</a></li><li><a href="./10-memory-system">第 10 篇：聊天机器人的记忆系统</a></li></ol><h2 id="原课程大纲-六个阶段" tabindex="-1">原课程大纲：六个阶段 <a class="header-anchor" href="#原课程大纲-六个阶段" aria-label="Permalink to &quot;原课程大纲：六个阶段&quot;">​</a></h2><p>课程目标是结合底层原理与工程开发，逐步使用 React、TypeScript 和 Node.js 构建聊天机器人。原始大纲确定了以下阶段与篇数范围，并没有给出全部 40 篇的逐篇标题。</p><table><thead><tr><th>阶段</th><th>篇数</th><th>主题</th></tr></thead><tbody><tr><td>第一阶段：AI 与大模型基础</td><td>01–07</td><td>LLM、Token、Embedding、Transformer、Attention、训练、推理</td></tr><tr><td>第二阶段：聊天机器人核心原理</td><td>08–13</td><td>Prompt、Messages、上下文窗口、多轮对话、Temperature、幻觉</td></tr><tr><td>第三阶段：聊天机器人工程开发</td><td>14–20</td><td>React、Node.js、SSE、流式输出、消息持久化、错误恢复、架构设计</td></tr><tr><td>第四阶段：RAG 与知识库</td><td>21–27</td><td>文档切分、Embedding、向量数据库、检索、重排序、引用溯源、质量评估</td></tr><tr><td>第五阶段：Agent 与高级能力</td><td>28–33</td><td>Function Calling、MCP、工具调用、长期记忆、任务规划、多智能体</td></tr><tr><td>第六阶段：生产级工程实践</td><td>34–40</td><td>安全、权限、性能、成本、监控、自动化测试、系统设计</td></tr></tbody></table><p>学完第三阶段，应能开发支持流式输出、多轮对话和历史记录的聊天机器人；后续阶段继续补充知识库、工具执行与生产运行能力。</p><h2 id="历史文章覆盖了什么" tabindex="-1">历史文章覆盖了什么？ <a class="header-anchor" href="#历史文章覆盖了什么" aria-label="Permalink to &quot;历史文章覆盖了什么？&quot;">​</a></h2><table><thead><tr><th>篇数</th><th>核心问题</th><th>已覆盖的主要内容</th></tr></thead><tbody><tr><td><a href="./01-how-chatgpt-works">01</a></td><td>ChatGPT 如何生成回答？</td><td>Tokenization、逐 Token 预测、Transformer 入门、预训练、聊天应用与模型的区别、React → Node.js → LLM 的整体流程</td></tr><tr><td><a href="./02-token-and-embedding">02</a></td><td>文字如何变成数字与向量？</td><td>Token ID、Embedding、语义空间、余弦相似度、Embedding API、Token 成本、向量方向与投影方向问答</td></tr><tr><td><a href="./03-transformer-attention">03</a></td><td>模型如何利用上下文？</td><td>Self-Attention、Q/K/V、注意力公式、多头注意力、Causal Mask、FFN、残差与归一化、应用提供聊天历史的责任</td></tr><tr><td><a href="./04-position-encoding">04</a></td><td>模型如何知道 Token 顺序？</td><td>可学习与正弦位置编码、二维旋转、RoPE 的相对位置关系、位置编码与因果掩码的区别</td></tr><tr><td><a href="./05-llm-training">05</a></td><td>模型能力从哪里来？</td><td>随机初始化、下一个 Token 预测、交叉熵 Loss、反向传播、预训练、SFT、偏好对齐、训练与使用现有模型的取舍</td></tr><tr><td><a href="./06-inference">06</a></td><td>回答如何逐步生成和传输？</td><td>Prefill、Decode、KV Cache、Temperature、Top-p、TTFT、TPS、延迟、Node.js 与 React 流式示例、性能优化</td></tr><tr><td><a href="./07-model-limitations">07</a></td><td>模型有哪些能力边界？</td><td>上下文预算、长上下文遗漏、幻觉类型、低温度的局限、数学与逻辑错误、RAG 的局限、证据不足时拒答</td></tr><tr><td><a href="./08-prompt-messages">08</a></td><td>应用如何组织模型输入？</td><td>Prompt 与 Messages、角色、System/User Prompt、Few-shot、结构化输出与 Zod 校验、Prompt Injection、最小多轮请求</td></tr><tr><td><a href="./09-conversation-memory">09</a></td><td>应用如何管理历史与记忆？</td><td>全量历史、滑动窗口、摘要、记忆检索、短期与长期记忆、ConversationManager、Token 预算裁剪、PostgreSQL 与 Redis 的职责</td></tr></tbody></table><p>这些文章形成了三条相互衔接的知识线：</p><ul><li><strong>模型原理：</strong> 01 总览 → 02 文本表示 → 03 上下文计算 → 04 位置信息 → 05 训练 → 06 推理 → 07 能力边界。</li><li><strong>对话输入：</strong> 08 组织角色、指令和示例 → 09 选择并管理历史、摘要与记忆。</li><li><strong>工程预习：</strong> 01 展示整体架构，06 展示流式链路，08 展示请求与校验，09 展示会话与存储。第三阶段将把这些局部示例整合为可运行的应用。</li></ul><h2 id="第-10-篇之前的衔接检查" tabindex="-1">第 10 篇之前的衔接检查 <a class="header-anchor" href="#第-10-篇之前的衔接检查" aria-label="Permalink to &quot;第 10 篇之前的衔接检查&quot;">​</a></h2><p>第 10–12 篇尚无已确认的逐篇题目。<a href="./01-how-chatgpt-works">第 01 篇</a>的思考题曾明确预告第 13 篇《为什么大语言模型会产生幻觉？》，这是现有历史安排中的具体线索。</p><p>后续选题应结合实际覆盖范围，避免把已经讲过的知识直接换标题重讲：</p><ul><li>Temperature、Top-p 已在第 06 篇详细讲解，后续应用时回链该篇。</li><li>第 07 篇已经介绍幻觉、推理限制、RAG 局限和拒答。若沿用第 13 篇的预告，应增加错误分析、验证方法和具体案例，体现相较第 07 篇的深入内容。</li><li>Few-shot、结构化输出、Zod 与 Prompt Injection 已在第 08 篇出现；后续须明确新增的工程问题和学习目标。</li><li>第 09 篇已介绍长期记忆、向量检索和存储职责。第四、第五阶段将分别深入检索系统和 Agent 记忆，不应把这些入门介绍等同于完整实现。</li><li>第三阶段仍需要完成 React 聊天界面、Node.js 服务、SSE 协议处理、持久化、取消与错误恢复等系统化实战。</li></ul><h3 id="原稿校对状态" tabindex="-1">原稿校对状态 <a class="header-anchor" href="#原稿校对状态" aria-label="Permalink to &quot;原稿校对状态&quot;">​</a></h3><ul><li>01、02、05–09 已依据现有原稿恢复对应内容；这不代表所有文章均已完成线上部署与视觉验收。</li><li>03 已恢复 Q/K/V 的原稿补充问答，主文和 04 的完整原稿仍待核对。</li><li>提供的 09 原稿在测验介绍后结束；保留的练习题与学习解答已在该篇标为本地补充。</li></ul><p>每篇文章包含原理、工程案例、复习题，以及持续维护的「学习疑问与解答」。问题按所属知识点回填到对应文章。</p><h2 id="每篇教程的发布验收标准" tabindex="-1">每篇教程的发布验收标准 <a class="header-anchor" href="#每篇教程的发布验收标准" aria-label="Permalink to &quot;每篇教程的发布验收标准&quot;">​</a></h2><ul><li>每篇标题上方统一展示绿色篇数进度标签、所属阶段与预计阅读时间。篇数与阶段由课程文件名自动识别；新增教程须在 frontmatter 中填写 <code>readingTime</code>（单位：分钟，例如 <code>readingTime: &quot;12–15&quot;</code>），由主题统一渲染信息栏。</li><li>正文、公式、SVG、TypeScript 代码、交互实验与原始 ChatGPT 教程逐项核对，不得随意压缩或删减。</li><li><strong>每篇至少 3 道交互式选择题</strong>，每题包含选项、正确答案和解析；必须支持提交评分及重新作答。</li><li>维护「学习疑问与解答」，将学习过程中提出的问题归档到对应章节。</li><li>Vue 模板内展示源码时必须对 <code>&lt;</code>、<code>&amp;</code> 等字符进行 HTML 转义，或使用安全的代码渲染组件。</li><li>GitHub PR 构建通过后才能合并；合并后再次确认 GitHub Pages 部署结果，并检查桌面、移动端和交互功能。</li><li>构建通过不代表视觉 1:1：应以原始 ChatGPT 版本为基准检查，无法完全复现的差异必须明确记录。</li></ul>',22),o=[i];function l(n,s,h,c,m,p){return e(),a("div",null,o)}const g=t(r,[["render",l]]);export{u as __pageData,g as default};
